// Measure the stable reading area; body scrolling does not change its height.
const readingHeightCache109=new Map();
function availableReadingHeight109({viewportHeight,viewportTop=0,articleTop,navTop,controlsHeight=64,controlsGap=16,panelPadding=0}){const bottom=Number.isFinite(navTop)?Math.min(viewportTop+viewportHeight,navTop):viewportTop+viewportHeight;return Math.max(140,Math.floor(bottom-articleTop-controlsHeight-controlsGap-panelPadding-12))}
function measureReadingSpace109(){if(!session||session.step!==1)return;const panel=document.querySelector('#course-reading-panel'),article=document.querySelector('#course-reading-panel .course-reading'),controls=document.querySelector('#course-reading-panel .reading-controls');if(!panel||!article||!controls||!article.getBoundingClientRect)return;const menu=panel.querySelector('.section-menu');if(menu?.open)return;const viewport=window.visualViewport;const height=viewport?.height||window.innerHeight,width=viewport?.width||window.innerWidth,top=viewport?.offsetTop||0;if(!Number.isFinite(height))return;const rect=article.getBoundingClientRect();const articleTop=rect.top+(window.scrollY||0);const nav=document.querySelector('#nav'),navRect=nav?.getBoundingClientRect();const navFixed=nav&&getComputedStyle(nav).position==='fixed';const navTop=navFixed&&navRect?.height?navRect.top:undefined;const padding=parseFloat(getComputedStyle(panel.parentElement).paddingBottom)||0;const gap=parseFloat(getComputedStyle(controls).marginTop)||0;const controlsHeight=controls.getBoundingClientRect().height;const key=[session.id,width,height,top,articleTop,controlsHeight,gap,padding,navTop].join(':');let size=readingHeightCache109.get(key);if(size===undefined){size=availableReadingHeight109({viewportHeight:height,viewportTop:top,articleTop,navTop,controlsHeight,controlsGap:gap,panelPadding:padding});readingHeightCache109.set(key,size)}panel.style.setProperty('--course-content-height',size+'px')}
const previousAdaptiveBind109=bindReadingPanel;
bindReadingPanel=function(l){previousAdaptiveBind109(l);measureReadingSpace109()};
let adaptiveResizeTimer109;
function resizeReading109(){clearTimeout(adaptiveResizeTimer109);adaptiveResizeTimer109=setTimeout(()=>{readingHeightCache109.clear();measureReadingSpace109()},100)}
window.addEventListener('resize',resizeReading109);if(window.visualViewport)window.visualViewport.addEventListener('resize',resizeReading109);if(document.fonts?.ready)document.fonts.ready.then(measureReadingSpace109);
render();
